const SCHEMA = ["CREATE TABLE IF NOT EXISTS propostas ( numero TEXT PRIMARY KEY, status TEXT NOT NULL DEFAULT 'Rascunho', cliente TEXT NOT NULL DEFAULT '', projeto TEXT NOT NULL DEFAULT '', responsavel TEXT NOT NULL DEFAULT '', data TEXT NOT NULL DEFAULT '', validade TEXT NOT NULL DEFAULT '15 dias', objetivo TEXT NOT NULL DEFAULT '', entregas TEXT NOT NULL DEFAULT '', etapas TEXT NOT NULL DEFAULT '', prazos TEXT NOT NULL DEFAULT '', imposto_pct REAL NOT NULL DEFAULT 6, desconto_pct REAL NOT NULL DEFAULT 0, faixa INTEGER NOT NULL DEFAULT 1, token TEXT NOT NULL UNIQUE, briefing TEXT NOT NULL DEFAULT 'Não', pendencias TEXT NOT NULL DEFAULT '', data_envio TEXT NOT NULL DEFAULT '', followup TEXT NOT NULL DEFAULT '', followup_n INTEGER NOT NULL DEFAULT 0, contato_nome TEXT NOT NULL DEFAULT '', contato_whatsapp TEXT NOT NULL DEFAULT '', contato_email TEXT NOT NULL DEFAULT '', briefing_texto TEXT NOT NULL DEFAULT '', resposta_data TEXT NOT NULL DEFAULT '', resposta_nome TEXT NOT NULL DEFAULT '', resposta_obs TEXT NOT NULL DEFAULT '', visto_n INTEGER NOT NULL DEFAULT 0, visto_primeiro TEXT NOT NULL DEFAULT '', visto_ultimo TEXT NOT NULL DEFAULT '', resposta_meta TEXT NOT NULL DEFAULT '', cliente_id INTEGER, pag_entrada REAL NOT NULL DEFAULT -1, pag_entrada_txt TEXT NOT NULL DEFAULT '', pag_resto_txt TEXT NOT NULL DEFAULT '', pag_formas TEXT NOT NULL DEFAULT '', pag_obs TEXT NOT NULL DEFAULT '', origem_id TEXT UNIQUE, criado_em TEXT NOT NULL DEFAULT (datetime('now')) )", "CREATE TABLE IF NOT EXISTS itens ( id INTEGER PRIMARY KEY AUTOINCREMENT, numero TEXT NOT NULL, ordem INTEGER NOT NULL DEFAULT 0, servico TEXT NOT NULL DEFAULT '', descricao TEXT NOT NULL DEFAULT '', observacao TEXT NOT NULL DEFAULT '', qtd REAL NOT NULL DEFAULT 1, valor_unit REAL NOT NULL DEFAULT 0 )", "CREATE INDEX IF NOT EXISTS ix_itens_numero ON itens(numero)", "CREATE TABLE IF NOT EXISTS catalogo ( id INTEGER PRIMARY KEY AUTOINCREMENT, ordem INTEGER NOT NULL DEFAULT 0, servico TEXT NOT NULL, descricao TEXT NOT NULL DEFAULT '', condicao TEXT NOT NULL DEFAULT '', faixa1 REAL NOT NULL DEFAULT 0, faixa2 REAL NOT NULL DEFAULT 0, categoria TEXT NOT NULL DEFAULT 'Serviços' )", "CREATE TABLE IF NOT EXISTS condicoes ( id INTEGER PRIMARY KEY AUTOINCREMENT, ordem INTEGER NOT NULL DEFAULT 0, titulo TEXT NOT NULL, texto TEXT NOT NULL DEFAULT '' )", "CREATE TABLE IF NOT EXISTS config (chave TEXT PRIMARY KEY, valor TEXT NOT NULL DEFAULT '')", "CREATE TABLE IF NOT EXISTS usuarios (login TEXT PRIMARY KEY, sal TEXT NOT NULL, hash TEXT NOT NULL, totp TEXT NOT NULL DEFAULT '', totp_pend TEXT NOT NULL DEFAULT '', criado TEXT NOT NULL DEFAULT (datetime('now')))", "CREATE TABLE IF NOT EXISTS sessoes (hash TEXT PRIMARY KEY, login TEXT NOT NULL, expira INTEGER NOT NULL)", "CREATE TABLE IF NOT EXISTS falhas (ip TEXT NOT NULL, ts INTEGER NOT NULL)", "CREATE TABLE IF NOT EXISTS avisos ( id INTEGER PRIMARY KEY AUTOINCREMENT, criado TEXT NOT NULL DEFAULT (datetime('now')), assunto TEXT NOT NULL DEFAULT '', texto TEXT NOT NULL, whatsapp TEXT NOT NULL DEFAULT '', email TEXT NOT NULL DEFAULT '', enviado INTEGER NOT NULL DEFAULT 0 )", "CREATE TABLE IF NOT EXISTS clientes ( id INTEGER PRIMARY KEY AUTOINCREMENT, empresa TEXT NOT NULL, cnpj TEXT NOT NULL DEFAULT '', contato_nome TEXT NOT NULL DEFAULT '', contato_email TEXT NOT NULL DEFAULT '', contato_whatsapp TEXT NOT NULL DEFAULT '', site TEXT NOT NULL DEFAULT '', cidade TEXT NOT NULL DEFAULT '', obs TEXT NOT NULL DEFAULT '', hubspot_id TEXT NOT NULL DEFAULT '', criado_em TEXT NOT NULL DEFAULT (datetime('now')) )"];

const VERSAO = 'v8.2';
const TZ = 'America/Sao_Paulo';
const ST = ['Atendimento', 'Briefing', 'Rascunho', 'Enviada', 'Negociação', 'Fechada', 'Perdida'];
const ITER = 30000;            // custo do hash de senha (PBKDF2-SHA256)
const SESSAO_MS = 30 * 86400000;

// ---------- utilidades ----------
const enc = new TextEncoder();
const hex = b => [...new Uint8Array(b)].map(x => x.toString(16).padStart(2, '0')).join('');
const b64 = b => btoa(String.fromCharCode(...new Uint8Array(b)));
const rnd = n => hex(crypto.getRandomValues(new Uint8Array(n)));
const sha256 = async s => hex(await crypto.subtle.digest('SHA-256', enc.encode(s)));
async function pbkdf2(senha, sal, iter) {
  const k = await crypto.subtle.importKey('raw', enc.encode(senha), 'PBKDF2', false, ['deriveBits']);
  return b64(await crypto.subtle.deriveBits({ name: 'PBKDF2', hash: 'SHA-256', salt: enc.encode(sal), iterations: iter }, k, 256));
}
function iguais(a, b) { a = String(a); b = String(b); if (a.length !== b.length) return false; let r = 0; for (let i = 0; i < a.length; i++) r |= a.charCodeAt(i) ^ b.charCodeAt(i); return r === 0; }
// ---------- verificação em duas etapas (TOTP: Google Authenticator, 1Password, Authy) ----------
const B32 = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ234567';
function b32enc(bytes) { let bits = 0, val = 0, out = ''; for (const b of bytes) { val = (val << 8) | b; bits += 8; while (bits >= 5) { out += B32[(val >>> (bits - 5)) & 31]; bits -= 5; } val &= (1 << bits) - 1; } if (bits > 0) out += B32[(val << (5 - bits)) & 31]; return out; }
function b32dec(str) { let bits = 0, val = 0; const out = []; for (const c of String(str).replace(/=+$/, '').toUpperCase()) { const i = B32.indexOf(c); if (i < 0) continue; val = (val << 5) | i; bits += 5; if (bits >= 8) { out.push((val >>> (bits - 8)) & 255); bits -= 8; } val &= (1 << bits) - 1; } return new Uint8Array(out); }
async function totpCodigo(segredo, passo) {
  const key = await crypto.subtle.importKey('raw', b32dec(segredo), { name: 'HMAC', hash: 'SHA-1' }, false, ['sign']), buf = new ArrayBuffer(8), dv = new DataView(buf);
  dv.setUint32(0, Math.floor(passo / 4294967296)); dv.setUint32(4, passo >>> 0);
  const h = new Uint8Array(await crypto.subtle.sign('HMAC', key, buf)), o = h[19] & 15, n = ((h[o] & 127) << 24) | (h[o + 1] << 16) | (h[o + 2] << 8) | h[o + 3];
  return String(n % 1000000).padStart(6, '0');
}
async function totpOk(segredo, codigo) {
  const c = String(codigo || '').replace(/\D/g, ''); if (c.length !== 6) return false;
  const p = Math.floor(Date.now() / 30000); let ok = false;
  for (const d of [-1, 0, 1]) if (iguais(await totpCodigo(segredo, p + d), c)) ok = true;
  return ok;
}
const num = s => Number(String(s == null || s === '' ? '0' : s).replace(/[^\d,.-]/g, '').replace(/\./g, '').replace(',', '.')) || 0;   // texto pt-BR (importação)
const nj = (x, d = 0) => { if (x === '' || x == null) return d; const n = Number(x); return isFinite(n) ? n : d; };                                                           // número vindo da API
const cut = (s, n) => String(s == null ? '' : s).slice(0, n);
const fone = s => { const d = String(s || '').replace(/\D/g, ''); return d && d.length <= 11 ? '55' + d : d; };
const linhas = s => String(s || '').split('\n').map(l => l.trim()).filter(Boolean).map(l => l.split('|').map(x => x.trim()));

